import torch
from torch.utils.cpp_extension import load_inline

from task import input_t, output_t


_CPP_SOURCE = r"""
#include <torch/extension.h>

torch::Tensor fused_tile_cholesky_cuda(torch::Tensor input);
"""

_CUDA_SOURCE = r"""
#include <torch/extension.h>
#include <c10/cuda/CUDAException.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <int N>
__global__ void fused_left_looking_tile(
    const float* __restrict__ input,
    float* __restrict__ output
) {
    constexpr int LD = N + 1;
    extern __shared__ float tile[];
    const int tid = threadIdx.x;
    const long long base = static_cast<long long>(blockIdx.x) * N * N;
    const float* src = input + base;
    float* dst = output + base;

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int row = index / N;
        const int col = index - row * N;
        tile[row * LD + col] = row >= col ? src[index] : 0.0f;
    }
    __syncthreads();

    // The resident tile recursively grows the completed leading principal
    // factor one column at a time. Panel, solve, and update work stays fused.
    for (int k = 0; k < N; ++k) {
        if (tid == 0) {
            float diagonal = tile[k * LD + k];
            for (int j = 0; j < k; ++j) {
                const float value = tile[k * LD + j];
                diagonal = fmaf(-value, value, diagonal);
            }
            tile[k * LD + k] = sqrtf(fmaxf(diagonal, 1.0e-30f));
        }
        __syncthreads();

        const float diagonal = tile[k * LD + k];
        for (int row = k + 1 + tid; row < N; row += blockDim.x) {
            float value = tile[row * LD + k];
            for (int j = 0; j < k; ++j) {
                value = fmaf(
                    -tile[row * LD + j], tile[k * LD + j], value
                );
            }
            tile[row * LD + k] = value / diagonal;
        }
        __syncthreads();
    }

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int row = index / N;
        const int col = index - row * N;
        dst[index] = tile[row * LD + col];
    }
}

__global__ void grouped_warp_cholesky_32(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch
) {
    constexpr int N = 32;
    constexpr int LD = 33;
    constexpr int MATRICES_PER_BLOCK = 8;
    __shared__ float storage[MATRICES_PER_BLOCK * N * LD];
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int matrix = static_cast<int>(blockIdx.x) * MATRICES_PER_BLOCK + warp;
    if (matrix >= batch) {
        return;
    }

    float* tile = storage + warp * N * LD;
    const long long base = static_cast<long long>(matrix) * N * N;
    const float* src = input + base;
    float* dst = output + base;
    for (int index = lane; index < N * N; index += 32) {
        const int row = index / N;
        const int col = index - row * N;
        tile[row * LD + col] = row >= col ? src[index] : 0.0f;
    }
    __syncwarp();

    for (int k = 0; k < N; ++k) {
        if (lane == 0) {
            float diagonal = tile[k * LD + k];
            for (int j = 0; j < k; ++j) {
                const float value = tile[k * LD + j];
                diagonal = fmaf(-value, value, diagonal);
            }
            tile[k * LD + k] = sqrtf(fmaxf(diagonal, 1.0e-30f));
        }
        __syncwarp();
        if (lane > k) {
            float value = tile[lane * LD + k];
            for (int j = 0; j < k; ++j) {
                value = fmaf(-tile[lane * LD + j], tile[k * LD + j], value);
            }
            tile[lane * LD + k] = value / tile[k * LD + k];
        }
        __syncwarp();
    }

    for (int index = lane; index < N * N; index += 32) {
        const int row = index / N;
        const int col = index - row * N;
        dst[index] = tile[row * LD + col];
    }
}

__global__ void four_thread_rows_cholesky_128(
    const float* __restrict__ input,
    float* __restrict__ output
) {
    constexpr int N = 128;
    constexpr int LD = 129;
    extern __shared__ float tile[];
    const int tid = threadIdx.x;
    const int row = tid / 4;
    const int lane = tid % 4;
    const long long base = static_cast<long long>(blockIdx.x) * N * N;
    const float* src = input + base;
    float* dst = output + base;
    for (int index = tid; index < N * N; index += blockDim.x) {
        const int input_row = index / N;
        const int col = index - input_row * N;
        tile[input_row * LD + col] = input_row >= col ? src[index] : 0.0f;
    }
    __syncthreads();

    // Four adjacent threads cooperate on one row's recursive dot product.
    // The padded tile keeps the four partial streams bank-conflict free.
    for (int k = 0; k < N; ++k) {
        float dot = 0.0f;
        if (row >= k) {
            for (int j = lane; j < k; j += 4) {
                dot = fmaf(tile[row * LD + j], tile[k * LD + j], dot);
            }
        }
        dot += __shfl_down_sync(0xffffffff, dot, 2, 4);
        dot += __shfl_down_sync(0xffffffff, dot, 1, 4);
        if (row == k && lane == 0) {
            tile[k * LD + k] = sqrtf(
                fmaxf(tile[k * LD + k] - dot, 1.0e-30f)
            );
        }
        __syncthreads();

        if (row > k && lane == 0) {
            tile[row * LD + k] =
                (tile[row * LD + k] - dot) / tile[k * LD + k];
        }
        __syncthreads();
    }

    for (int index = tid; index < N * N; index += blockDim.x) {
        const int output_row = index / N;
        const int col = index - output_row * N;
        dst[index] = tile[output_row * LD + col];
    }
}

template <int N>
void launch_fused_tile(const torch::Tensor& input, torch::Tensor& output) {
    constexpr int shared_bytes = N * (N + 1) * sizeof(float);
    fused_left_looking_tile<N><<<input.size(0), N, shared_bytes>>>(
        input.data_ptr<float>(), output.data_ptr<float>()
    );
}

torch::Tensor fused_tile_cholesky_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3, "input must have shape (batch, n, n)");
    TORCH_CHECK(input.size(1) == input.size(2), "matrices must be square");

    const int n = static_cast<int>(input.size(1));
    auto output = torch::empty_like(input);
    const c10::cuda::CUDAGuard device_guard(input.device());
    if (n == 32) {
        const int blocks = (static_cast<int>(input.size(0)) + 7) / 8;
        grouped_warp_cholesky_32<<<blocks, 256>>>(
            input.data_ptr<float>(), output.data_ptr<float>(), input.size(0)
        );
    } else if (n == 64) {
        launch_fused_tile<64>(input, output);
    } else if (n == 128) {
        constexpr int shared_bytes = 128 * 129 * sizeof(float);
        static const cudaError_t configured = cudaFuncSetAttribute(
            four_thread_rows_cholesky_128,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            shared_bytes
        );
        C10_CUDA_CHECK(configured);
        four_thread_rows_cholesky_128<<<input.size(0), 512, shared_bytes>>>(
            input.data_ptr<float>(), output.data_ptr<float>()
        );
    } else {
        TORCH_CHECK(false, "fused tile supports n=32, 64, or 128");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
