def _recursive_cholesky_256(data: torch.Tensor) -> torch.Tensor:
    split = 128
    l11 = _EXTENSION.fused_tile_cholesky_cuda(
        data[:, :split, :split].contiguous()
    )
    l21_transpose = torch.linalg.solve_triangular(
        l11,
        data[:, split:, :split].transpose(-1, -2),
        upper=False,
    )
    l21 = l21_transpose.transpose(-1, -2)
