        data[:, split:, split:],
        l21,
        l21.transpose(-1, -2),
        beta=1.0,
        alpha=-1.0,
    )
    l22 = _EXTENSION.fused_tile_cholesky_cuda(schur.contiguous())

    output = torch.zeros_like(data)
    output[:, :split, :split] = l11
    output[:, split:, :split] = l21
    output[:, split:, split:] = l22
    return output


def custom_kernel(data: input_t) -> output_t:
    if data.shape[-1] <= 128:
