    constexpr int N = 128;
    constexpr int LD = 129;
    const int tid = threadIdx.x;
    const int row = tid / 2;
    const int lane = tid % 2;
    for (int k = 0; k < N; ++k) {
        float dot = 0.0f;
        if (row >= k) {
            for (int j = lane; j < k; j += 2) {
                dot = fmaf(tile[row * LD + j], tile[k * LD + j], dot);
